CREATE POLICY group_practice_logo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='group-practice-logos');
CREATE POLICY group_practice_logo_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='group-practice-logos' AND (public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),(storage.foldername(name))[1]::uuid)));
CREATE POLICY group_practice_logo_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='group-practice-logos' AND (public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),(storage.foldername(name))[1]::uuid))) WITH CHECK(bucket_id='group-practice-logos' AND (public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),(storage.foldername(name))[1]::uuid)));